components.css:
.ds-preview-begin-link{font-family:var(--sans, -apple-system, BlinkMacSystemFont, "PingFang SC", "Microsoft YaHei", sans-serif);background:var(--night, #17382f);color:var(--paper, #f5f4ee)}.ds-preview-begin-link a:focus-visible,.ds-preview-begin-link button:focus-visible{outline:2px solid currentColor;outline-offset:5px}.ds-preview-begin-link button{font:inherit;cursor:pointer}.ds-preview-begin-link button:disabled{cursor:default}
.ds-begin-link { display: inline-flex; align-items: center; gap: 1rem; min-height: 3rem; padding: 0.6rem 1rem; margin-top: 1.75rem; background: var(--signal, #f0cb72); color: var(--night, #17382f); text-decoration: none; font-size: 0.9375rem; font-weight: 600; }
.ds-begin-link svg { width: 1.25rem; height: 1.25rem; }
.ds-begin-link:hover { background: var(--paper, #f5f4ee); }

@media(prefers-reduced-motion:no-preference){.ds-begin-link{transition:color 140ms ease-out,background-color 140ms ease-out}}

.ds-preview-route-control{font-family:var(--sans, -apple-system, BlinkMacSystemFont, "PingFang SC", "Microsoft YaHei", sans-serif);background:var(--night, #17382f);color:var(--paper, #f5f4ee)}.ds-preview-route-control a:focus-visible,.ds-preview-route-control button:focus-visible{outline:2px solid currentColor;outline-offset:5px}.ds-preview-route-control button{font:inherit;cursor:pointer}.ds-preview-route-control button:disabled{cursor:default}
.ds-route-controls { display: flex; gap: 0.5rem; }
.ds-route-controls button { display: grid; place-items: center; width: 2.75rem; height: 2.75rem; border: 1px solid var(--night-muted, #c1d0c6); color: var(--paper, #f5f4ee); background: transparent; }
.ds-route-controls button:hover:enabled { background: var(--paper, #f5f4ee); color: var(--night, #17382f); }
.ds-route-controls button:disabled { color: #789389; border-color: #789389; }
.ds-route-controls svg { width: 1.25rem; height: 1.25rem; }

@media(prefers-reduced-motion:no-preference){.ds-route-controls button{transition:color 140ms ease-out,background-color 140ms ease-out}}

.ds-preview-route-link-current{font-family:var(--sans, -apple-system, BlinkMacSystemFont, "PingFang SC", "Microsoft YaHei", sans-serif);background:var(--paper, #f5f4ee);color:var(--ink, #20392f)}.ds-preview-route-link-current a:focus-visible,.ds-preview-route-link-current button:focus-visible{outline:2px solid currentColor;outline-offset:5px}.ds-preview-route-link-current button{font:inherit;cursor:pointer}.ds-preview-route-link-current button:disabled{cursor:default}
.ds-route-list { display: grid; }
.ds-route-list a { position: relative; display: grid; grid-template-columns: 2rem minmax(0, 1fr); gap: 0.5rem; align-items: center; min-height: 2.75rem; padding-inline: 0.5rem; text-decoration: none; border-radius: 0; }
.ds-route-number { color: var(--muted, #56645c); font-size: var(--type-meta, 0.875rem); font-variant-numeric: tabular-nums; }
.ds-route-label { font-size: 1rem; }
.ds-route-list a:hover { background: #e4e8dc; }
.ds-route-list a[aria-current="location"] { background: var(--signal, #f0cb72); color: var(--night, #17382f); font-weight: 600; }
.ds-route-list a[aria-current="location"] .ds-route-label { text-decoration: underline; text-underline-offset: 0.25em; }
.ds-route-list a[aria-current="location"] .ds-route-number { color: var(--signal-ink, #57441c); }
.ds-route-list{list-style:none;padding:0;margin:0}.ds-route-list a{color:inherit}
.ds-route-list a[aria-current="location"]{color:var(--night,#17382f)}

.ds-preview-destination{font-family:var(--sans, -apple-system, BlinkMacSystemFont, "PingFang SC", "Microsoft YaHei", sans-serif);background:var(--night, #17382f);color:var(--paper, #f5f4ee)}.ds-preview-destination a:focus-visible,.ds-preview-destination button:focus-visible{outline:2px solid currentColor;outline-offset:5px}.ds-preview-destination button{font:inherit;cursor:pointer}.ds-preview-destination button:disabled{cursor:default}
.ds-route-window { min-width: 0; padding-top: 0.5rem; }
.ds-window-head { display: flex; align-items: center; justify-content: space-between; gap: 1rem; color: var(--night-muted, #c1d0c6); font-size: var(--type-meta, 0.875rem); }
.ds-window-head [data-current-position] { font-variant-numeric: tabular-nums; }
.ds-destination { display: flex; align-items: center; justify-content: space-between; gap: 1.5rem; padding-block: 1.25rem; }
.ds-destination-name { display: inline-block; color: var(--signal, #f0cb72); font: 600 var(--type-display, 4.75rem)/1.25 var(--serif, "Songti SC", "STSong", "SimSun", Georgia, serif); letter-spacing: 0.02em; }
.ds-road { position: relative; height: 2.5rem; margin-top: 0.25rem; --route-progress: 0; }
.ds-road::before { content: ""; position: absolute; top: 1rem; inset-inline: 0; border-top: 1px dashed var(--night-muted, #c1d0c6); }
.ds-road-fill { position: absolute; top: 1rem; inset-inline: 0; height: 2px; background: var(--signal, #f0cb72); transform-origin: left; transform: scaleX(var(--route-progress, 0)); transition: transform 280ms var(--ease-out, cubic-bezier(0.16, 1, 0.3, 1)); }
.ds-road-marker { position: absolute; top: 0; left: 0; width: 2rem; height: 2rem; color: var(--signal, #f0cb72); background: var(--night, #17382f); transition: transform 280ms var(--ease-out, cubic-bezier(0.16, 1, 0.3, 1)); }
.ds-road-endpoints { display: flex; justify-content: space-between; color: var(--night-muted, #c1d0c6); font-size: var(--type-meta, 0.875rem); }

@media(prefers-reduced-motion:reduce){.ds-road-marker,.ds-road-fill{transition:none}}

.ds-preview-prose{font-family:var(--sans, -apple-system, BlinkMacSystemFont, "PingFang SC", "Microsoft YaHei", sans-serif);background:var(--paper, #f5f4ee);color:var(--ink, #20392f)}.ds-preview-prose a:focus-visible,.ds-preview-prose button:focus-visible{outline:2px solid currentColor;outline-offset:5px}.ds-preview-prose button{font:inherit;cursor:pointer}.ds-preview-prose button:disabled{cursor:default}
.ds-prose { max-width: 42rem; padding-top: 1.75rem; font: 400 var(--type-body, 1.25rem)/1.95 var(--serif, "Songti SC", "STSong", "SimSun", Georgia, serif); }
.ds-prose p + p { margin-top: 1.1em; }
.ds-prose p{margin:0;text-wrap:pretty;overflow-wrap:break-word}
@media(max-width:48rem){.ds-prose{font-size:1.125rem;padding-top:1.5rem}}
